   [183]={next_id=184, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="对，对啊！我是说如果我满意了，这里倒是一个值得被我记住的地方，可以安排进下次假期的休假地点。", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [184]={next_id=185, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而且，接待人也必须是你才行，明白吗？", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
