   [186]={next_id=187, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="纸花落在你们肩上，又被尤加利随手掸开。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [187]={next_id=188, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她看了一眼四周。那些观众还在笑，还在谈论刚才每一场比赛，有人夸胜者，也有人拍着败者的肩膀，说着“下次再来”。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
