   [189]={next_id=190, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这地方……确实比虚蚀域要安全得多，所以才会有那种麻烦的规则。", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
